	"github.com/metacubex/mihomo/common/atomic"
	failedTestMux     sync.Mutex
	failedTimes       int
	failedTime        time.Time
	failedTesting     atomic.Bool
	failureGate       flclashFailureGate
		failedTesting:     atomic.NewBool(false),
func (gb *GroupBase) onDialFailed(adapterType C.AdapterType, err error, fn func()) {
	if adapterType == C.Direct || adapterType == C.Compatible || adapterType == C.Reject || adapterType == C.Pass || adapterType == C.RejectDrop {
		return
	}

	if errors.Is(err, C.ErrNotSupport) {
		return
	}

	go func() {
		if strings.Contains(err.Error(), "connection refused") {
			fn()
			return
		}

		gb.failedTestMux.Lock()
		defer gb.failedTestMux.Unlock()

		gb.failedTimes++
		if gb.failedTimes == 1 {
			log.Debugln("ProxyGroup: %s first failed", gb.Name())
			gb.failedTime = time.Now()
		} else {
			if time.Since(gb.failedTime) > time.Duration(gb.testTimeout)*time.Millisecond {
				gb.failedTimes = 0
				return
			}

			log.Debugln("ProxyGroup: %s failed count: %d", gb.Name(), gb.failedTimes)
			if gb.failedTimes >= gb.maxFailedTimes {
				log.Warnln("because %s failed multiple times, activate health check", gb.Name())
				fn()
			}
		}
	}()
}

func (gb *GroupBase) healthCheck() {
	if gb.failedTesting.Load() {
		return
	}

	gb.failedTesting.Store(true)
	wg := sync.WaitGroup{}
	for _, proxyProvider := range gb.providers {
		wg.Add(1)
		proxyProvider := proxyProvider
		go func() {
			defer wg.Done()
			proxyProvider.HealthCheck()
		}()
	}

	wg.Wait()
	gb.failedTesting.Store(false)
	gb.failedTimes = 0
}

func (gb *GroupBase) onDialSuccess() {
	if !gb.failedTesting.Load() {
		gb.failedTimes = 0
	}
}
func (gb *GroupBase) onDialFailed(proxy C.Proxy, network string, err error, fn func()) {
	adapterType := proxy.Type()
	if adapterType == C.Direct || adapterType == C.Compatible || adapterType == C.Reject || adapterType == C.Pass || adapterType == C.RejectDrop {
		return
	}
	if err == nil || errors.Is(err, C.ErrNotSupport) || errors.Is(err, context.Canceled) {
		return
	}
	// Preserve the configured failure threshold/window and the existing fast
	// path for connection refusal, but admit at most one health check.
	if !gb.failureGate.failure(network, proxy.Name(), time.Now(),
		time.Duration(gb.testTimeout)*time.Millisecond, gb.maxFailedTimes,
		strings.Contains(err.Error(), "connection refused")) {
		return
	}
	go func() {
		defer gb.failureGate.finish()
		log.Warnln("because %s failed multiple times, activate health check", gb.Name())
		fn()
	}()
}

func (gb *GroupBase) healthCheck() {
	var wg sync.WaitGroup
	for _, proxyProvider := range gb.providers {
		proxyProvider := proxyProvider
		wg.Add(1)
		go func() {
			defer wg.Done()
			proxyProvider.HealthCheck()
		}()
	}
	wg.Wait()
}

func (gb *GroupBase) onDialSuccess(proxy C.Proxy, network string) {
	gb.failureGate.success(network, proxy.Name())
}

